import{_ as o,l as i,o as e,c as s,v as r,p as n,x as t,d,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"子词的动机","description":"","frontmatter":{"title":"子词的动机","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/why-subword.md","filePath":"llm/why-subword.md","lastUpdated":1789023840000}'),p={name:"llm/why-subword.md"};function m(A,a,B,c,u,_){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="子词的动机" tabindex="-1">子词的动机 <a class="header-anchor" href="#子词的动机" aria-label="Permalink to &quot;子词的动机&quot;">​</a></h1><div class="epigraph"><p>整词词表把未见过的写法当成全新符号，梯度到不了那一行；切成可组合的短片段，让稀有写法去点那些更新更勤的行。</p><footer>—— 据 Sennrich, Haddow &amp; Birch, Neural Machine Translation of Rare Words with Subword Units, ACL 2016 整理</footer></div><p><a href="/llm/negative-sampling">负采样</a>让大词表上的训练算得动。本课不重写 \\(k\\) 个负例。缺口是：即使算得动，<strong>整词</strong> \\(V\\) 仍有两处硬伤——未登录词没有行，稀有词形的行几乎不更新。方法是改粒度：把词切成子词，使新写法由旧片段拼出。本课只讲动机；BPE 的合并算法、词表大小与 UNK 协议，是主干课<a href="/llm/token-as-discrete-unit">离散符号与词表</a>之后的事，这里不重写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>skip-gram 给每个词型一行。语料里出现一次的姓名、拼写变体、形态变化，各自占一行，梯度只来自那一次窗口。未见过的词在推理时没有行——one-hot 与查找表都无法索引。放大 \\(|V|\\) 只是把更长的尾巴收进来，永远有更长的尾巴，内存按 \\(|V|d\\) 涨。缺口不是再换 NEG 的 \\(k\\)，而是让不同词型<strong>共享</strong>片段对应的向量，使「第一次见到的复合写法」仍能查到若干已训练的行。</p><p>形态丰富的语言、代码标识符、数字，最能暴露整词假设的失败：人能从词缀与词根读出结构，整词表把结构当成新原子。子词把这条结构暴露给查找表，而不需要句法树。</p><h3 id="子词不是字符级模型的同义词" tabindex="-1">子词不是字符级模型的同义词 <a class="header-anchor" href="#子词不是字符级模型的同义词" aria-label="Permalink to &quot;子词不是字符级模型的同义词&quot;">​</a></h3><p>每个字符一行也能覆盖未登录写法，但序列变长数倍，窗口与后来的 RNN 都更难捕获词级共现。子词介于词与字符之间：常见词往往整块保留，罕见词才被拆开。这是数据驱动的折中，不是「越短越好」。把动机理解成「全部切成字节」，后课词表压缩与长度预算会对不上。本课也不把某一套合并规则写成唯一实现。</p><p><span class="marginnote">共享片段意味着同一行会被许多词型点到，更新更勤——与嵌入查找课「长尾行学不透、短符号行更新勤」是同一现象的预告。本课只给动机，不定义 gather。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选定一个有限的片段词表 \\(V_{\\mathrm{sub}}\\)，切分函数把字符串映到 \\(V_{\\mathrm{sub}}\\) 上的序列。训练与推理用同一套切分，保证往返协议稍后可以讨论。模型看见的是片段 id 序列，不再看见「词」这一层（除非切分碰巧把整词留下）。分布假设改在片段上：共现窗口可以跨过原来的词边界。这会把词内结构与词间句法混在同一窗口里，是代价，也是覆盖未登录的来源。</p>',11)),(e(),n(h,null,{default:t(()=>[E(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20WORD%5B%22%E6%95%B4%E8%AF%8D%E8%A1%A8%22%5D%20--%3E%20OOV%5B%22%E6%9C%AA%E8%A7%81%E5%86%99%E6%B3%95%E6%97%A0%E8%A1%8C%22%5D%0A%20%20WORD%20--%3E%20TAIL%5B%22%E9%95%BF%E5%B0%BE%E8%A1%8C%E5%87%A0%E4%B9%8E%E4%B8%8D%E6%9B%B4%E6%96%B0%22%5D%0A%20%20SUB%5B%22%E5%AD%90%E8%AF%8D%E7%89%87%E6%AE%B5%22%5D%20--%3E%20SHARE%5B%22%E7%A8%80%E6%9C%89%E5%86%99%E6%B3%95%E7%82%B9%E5%88%B0%E5%8B%A4%E6%9B%B4%E6%96%B0%E7%9A%84%E8%A1%8C%22%5D%0A%20%20SUB%20--%3E%20LEN%5B%22%E5%BA%8F%E5%88%97%E5%8F%98%E9%95%BF%20%E4%BD%86%E7%9F%AD%E4%BA%8E%E7%BA%AF%E5%AD%97%E7%AC%A6%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>覆盖来自组合：新词若由旧片段拼成，嵌入几何至少有各片段的向量可加或可拼接（如何聚合成词向量是后话；序列模型干脆不再聚合，直接把片段当时间步）。统计来自共享：高频词缀的行被反复更新，低频词干也能搭车。失败模式：切得过碎，窗口装不下原来的句法邻域；切得过粗，未登录仍大量出现。动机课只要求承认这条权衡存在。</p><p>同一字符串的切分必须在训练与推理上一致，否则查找表的行对不上，往返也无法定义。这是协议，不是模型容量。词表 \\(|V_{\\mathrm{sub}}|\\) 越大，整词越容易被留下，未登录越少，但嵌入表内存按行数涨，且长尾行又回来。动机是把「无限词型」换成「有限片段上的序列」，具体数字交给主干词表课。</p><p>数字与代码往往被拆成字符或字节级片段，这是整词假设在开放词类上的必然，不是分词 bug。人名与 URL 同理：第一次出现也必须能切出已有行，否则又回到 UNK 一条向量扛所有未知。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写出 BPE 的 pair 统计与合并表，不讨论 byte fallback。下一课<a href="/llm/embed-as-lookup-motive">嵌入作为查找</a>假定已经有有限 id，把表示收成 gather。主干的词表课会从离散符号重新起笔；本课只在深度学习基础里留下「为何不要死守整词」这一缺口。后课默认：开放词汇需要子词粒度；具体算法不在本课。字符 CNN 或混合切分是其它组合方式，同样服务于覆盖，不在此并列。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>整词表无法索引未登录写法，长尾行学不透。</li><li>子词让稀有写法复用频繁更新的片段行，序列长度介于词与字符之间。</li><li>动机是覆盖与共享，不是某一种合并算法。</li><li>BPE 与 UNK 协议交给主干词表课，本课不重写。</li><li>训练与推理必须共用同一套切分，否则行对不上。</li><li>出处：Sennrich, Haddow &amp; Birch, ACL 2016。</li></ul>',8))])}const D=o(p,[["render",m]]);export{f as __pageData,D as default};
